SELECT pp.id AS position_id, pp.opened_at AS opened_ksa_in_this_mysql_session, CONVERT_TZ(pp.opened_at, '+03:00', '+00:00') AS opened_utc, pp.closed_at AS closed_ksa_in_this_mysql_session, CONVERT_TZ(pp.closed_at, '+03:00', '+00:00') AS closed_utc, UNIX_TIMESTAMP(pp.opened_at) AS opened_epoch_seconds, @@session.time_zone AS query_session_time_zone FROM paper_position pp WHERE pp.signal_id = 89469